5	 * Pure UI-state predicate, moved out of PDFExportService (it was a static
6	 * parked on the service). The expenses page feeds it via a $derived.
7	 */
8	
9	export interface PDFExportUIState {
10		filteredExpensesCount: number;
11		selectedCategoryIds: string[];
12		showUncategorizedOnly: boolean;
13		isExporting: boolean;
14	}
15	
16	export function shouldEnablePDFExport(state: PDFExportUIState): boolean {
17		if (state.isExporting) return false;
18		if (state.filteredExpensesCount === 0) return false;
19		if (state.selectedCategoryIds.length === 0) return false;
20		if (state.showUncategorizedOnly) return false;
21		return true;
22	}
